// t467 probe: open, rebuild and first flip at depth, through GraphSnapshot as the app uses it.
use std::time::Instant;
use trunk_git::graph::{CommitMemo, capture_remembering};
use trunk_git::graph_input::{GraphSnapshot, RefVisibility};

fn ms(t: Instant) -> f64 { t.elapsed().as_secs_f64() * 1000.0 }

fn main() {
    let path = std::env::args().nth(1).unwrap();
    let memo = CommitMemo::default();
    let mut repo = git2::Repository::open(&path).unwrap();
    let t = Instant::now();
    let source = capture_remembering(&mut repo, &memo).unwrap();
    let cap = ms(t);
    let t = Instant::now();
    let snap = GraphSnapshot::new(source, RefVisibility::default());
    let layout = ms(t);
    drop(snap);
    println!("open: capture {cap:.1} ms, layout {layout:.1} ms");
    for round in 0..7 {
        let mut repo = git2::Repository::open(&path).unwrap();
        let t = Instant::now();
        let source = capture_remembering(&mut repo, &memo).unwrap();
        let cap = ms(t);
        let t = Instant::now();
        let snap = GraphSnapshot::new(source, RefVisibility::default());
        let layout = ms(t);
        let t = Instant::now();
        let flipped = snap.with_worktree_dirty(!snap.worktree_dirty());
        let flip = ms(t);
        drop(flipped);
        println!("rebuild {round}: capture {cap:.1} ms, layout {layout:.1} ms, first flip {flip:.1} ms");
    }
}
